using Avalonia;
using Avalonia.Controls;
using Avalonia.Headless;
using Avalonia.Interactivity;
using Avalonia.Threading;
using Avalonia.VisualTree;
using Avalonia.Media;
namespace ProjectDesk;
internal static class FormattingValidation {
 public static int Run(string file,string output){
  Directory.CreateDirectory(output);AppBuilder.Configure<DesktopApp>().UseSkia().UseHeadless(new AvaloniaHeadlessPlatformOptions{UseHeadlessDrawing=false}).SetupWithoutStarting();int checks=0;
  void Assert(bool test,string message){if(!test)throw new Exception(message);checks++;}
  static bool IsDark(Color c)=>0.2126*c.R+0.7152*c.G+0.0722*c.B<0.4*255;
  void Pump(){Dispatcher.UIThread.RunJobs();AvaloniaHeadlessPlatform.ForceRenderTimerTick(3);Dispatcher.UIThread.RunJobs();}
  using var session=new ProjectSession();session.Open(file);var task=session.Tasks.First(t=>!t.IsSummary);string? original=task.Name;
  var prefPath=Path.Combine(output,"format-preferences-"+Guid.NewGuid()+".json");var window=new PlannerWindow(session,prefPath);window.Show();window.SetCompactWorkspace(false);Pump();
  window.Sheet.Grid.SelectedItem=window.Sheet.Grid.ItemsSource!.OfType<TaskTableRow>().Single(r=>r.Uid==task.Uid);window.Sheet.Grid.CurrentColumn=window.Sheet.Grid.Columns.Single(c=>Equals(c.Header,"Task Name"));
  window.GetVisualDescendants().OfType<RibbonModule>().Single().SelectTab("Task");Pump();var bold=window.GetVisualDescendants().OfType<Button>().Single(b=>Equals(b.Content,"B"));
  string boldTip=ToolTip.GetTip(bold)?.ToString()??"";Assert(boldTip==(OperatingSystem.IsMacOS()?"Bold (⌘B)":"Bold (Ctrl+B)"),"Bold tooltip does not name the platform shortcut: "+boldTip);
  bold.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Pump();Assert(window.Formatting.Get("Task",task.Uid,"Name").Bold==true,"Bold button did not apply to cell");Assert(session.Document!.Tasks.GetByUid(task.Uid).Name==original&&!session.HasEdits,"Appearance changed project text or dirtied MPP");
  window.Formatting.Edit(session.HistoryPosition,d=>d.Cells[FormattingStore.CellKey("Task",task.Uid,"Name")]=new(){Bold=true,Italic=true,Underline="Double",Strike="Single",Foreground="#C00000",Highlight="#FFF2CC",Size=16,Alignment="Center",Spacing=.5});Pump();
  var block=window.Sheet.Grid.GetVisualDescendants().OfType<TextBlock>().First(t=>t.DataContext is TaskTableRow row&&row.Uid==task.Uid&&Equals(t.Tag,"Name"));Assert(block.FontWeight==FontWeight.Bold&&block.FontStyle==FontStyle.Italic,"Visible font styles did not render");Assert(block.TextDecorations?.Count>=3,"Underline and strike did not render");Assert(block.Foreground is SolidColorBrush b&&b.Color==Color.Parse("#C00000"),"Font color did not render");Assert(block.Background is SolidColorBrush h&&h.Color==Color.Parse("#FFF2CC"),"Highlight did not render");Assert(block.TextAlignment==TextAlignment.Center&&block.LetterSpacing==.5,"Alignment/spacing did not render");
  using(var frame=window.CaptureRenderedFrame()!)frame.Save(Path.Combine(output,"formatted-task-grid.png"));
  window.Formatting.Undo();Pump();Assert(window.Formatting.Get("Task",task.Uid,"Name").Bold==true&&window.Formatting.Get("Task",task.Uid,"Name").Foreground==null,"Format Undo failed");window.Formatting.Redo();Pump();Assert(window.Formatting.Get("Task",task.Uid,"Name").Foreground=="#C00000","Format Redo failed");
  window.Sheet.Grid.Focus();window.Sheet.Grid.BeginEdit();Pump();var editor=window.Sheet.Grid.GetVisualDescendants().OfType<TextBox>().Single(t=>t.Name=="CellTextBox"&&t.IsVisible);Assert(editor.FontStyle==FontStyle.Italic&&editor.FontSize==16,"Cell editor lost formatting");window.Formatting.Edit(session.HistoryPosition,d=>d.Cells[FormattingStore.CellKey("Task",task.Uid,"Name")]=window.Formatting.Get("Task",task.Uid,"Name") with{Bold=false});Pump();Assert(editor.FontWeight==FontWeight.Normal,"Live formatting did not update active editor");window.Formatting.Undo();Pump();Assert(editor.FontWeight==FontWeight.Bold,"Live formatting Undo did not update editor");editor.Text=original+" styled edit";Assert(window.Sheet.Grid.CommitEdit(),"Styled cell could not commit");Pump();Assert(session.Document!.Tasks.GetByUid(task.Uid).Name==original+" styled edit","Styled editing lost text");session.Undo();window.RefreshForValidation();Pump();
  block=window.Sheet.Grid.GetVisualDescendants().OfType<TextBlock>().First(t=>t.DataContext is TaskTableRow row&&row.Uid==task.Uid&&Equals(t.Tag,"Name"));var originalStyle=window.Formatting.Get("Task",task.Uid,"Name");
  window.Formatting.Edit(session.HistoryPosition,d=>d.Cells[FormattingStore.CellKey("Task",task.Uid,"Name")]=originalStyle with{Caps="All caps",Vertical="Superscript",BorderColor="#4472C4",BorderWidth=2});Pump();Assert(block.Text==((TaskTableRow)block.DataContext!).Cells["Name"]!.ToUpperInvariant()&&block.FontSize==12,$"All caps / superscript did not render: {block.Text} / {block.FontSize}");Assert(session.Document!.Tasks.GetByUid(task.Uid).Name==original,"Display capitalization changed stored text");
  window.Formatting.Edit(session.HistoryPosition,d=>d.Cells[FormattingStore.CellKey("Task",task.Uid,"Name")]=originalStyle with{Caps="Small caps"});Pump();Assert(block.Inlines!.Count==((TaskTableRow)block.DataContext!).Cells["Name"]!.Length,"Small caps did not retain per-character casing");
  window.Formatting.Edit(session.HistoryPosition,d=>d.Cells[FormattingStore.CellKey("Task",task.Uid,"Name")]=originalStyle with{Wrap=true});session.EditCells([new TextCellChange(task.Uid,"Name",string.Join(" ",Enumerable.Repeat("Long planning task",30)))],"Wrap test");window.RefreshForValidation();Pump();Assert(double.IsNaN(window.Sheet.Grid.RowHeight)&&window.Sheet.Grid.GetVisualDescendants().OfType<TextBlock>().Any(t=>t.DataContext is TaskTableRow r&&r.Uid==task.Uid&&Equals(t.Tag,"Name")&&t.TextWrapping==TextWrapping.Wrap),"Wrapped cells did not enable variable row height");Assert(window.Sheet.Grid.GetVisualDescendants().OfType<DataGridRow>().Any(r=>r.DataContext is TaskTableRow row&&row.Uid==task.Uid&&r.Bounds.Height>40),"Wrapped task text remained clipped");session.Undo();window.RefreshForValidation();window.Formatting.Edit(session.HistoryPosition,d=>{d.Cells[FormattingStore.CellKey("Task",task.Uid,"Name")]=originalStyle;d.ChartColors["Task"]="#7030A0";d.ChartColors["Links"]="#ED7D31";d.ChartColors["Weekend"]="#EEF3F8";});Pump();
  using(var frame=window.CaptureRenderedFrame()!)frame.Save(Path.Combine(output,"chart-colors-grid.png"));
  window.SelectPreviewTab(2);Pump();var resources=window.GetVisualDescendants().OfType<DataGrid>().Single(g=>g.IsVisible&&g.Columns.Any(c=>Equals(c.Header,"Standard Rate")));var resource=resources.ItemsSource!.OfType<SheetRecord>().First();window.Formatting.Edit(session.HistoryPosition,d=>d.Cells[FormattingStore.CellKey("Resource",resource.Uid,"Name")]=originalStyle);Pump();var resourceText=resources.GetVisualDescendants().OfType<TextBlock>().First(t=>t.DataContext is SheetRecord r&&r.Uid==resource.Uid&&Equals(t.Tag,"Name"));Assert(resourceText.FontStyle==FontStyle.Italic&&resourceText.FontSize==16,"Resource formatting did not render");resources.SelectedItem=resource;resources.CurrentColumn=resources.Columns.Single(c=>Equals(c.Header,"Resource Name"));resources.Focus();Assert(resources.BeginEdit(),"Resource formatted editor failed to open");Pump();Assert(resources.GetVisualDescendants().OfType<TextBox>().Single(t=>t.Name=="CellTextBox"&&t.IsVisible).FontSize==16,"Resource editor lost font size");resources.CancelEdit();
  if(window.AssignmentCount>0){window.SelectPreviewTab(3);Pump();var assignments=window.GetVisualDescendants().OfType<DataGrid>().Single(g=>g.IsVisible&&g.Columns.Any(c=>Equals(c.Header,"Actual Work")));var assignment=assignments.ItemsSource!.OfType<SheetRecord>().First();window.Formatting.Edit(session.HistoryPosition,d=>d.Cells[FormattingStore.CellKey("Assignment",assignment.Uid,"Units")]=originalStyle);Pump();Assert(assignments.GetVisualDescendants().OfType<TextBlock>().Any(t=>t.DataContext is SheetRecord r&&r.Uid==assignment.Uid&&Equals(t.Tag,"Units")&&t.FontStyle==FontStyle.Italic),"Assignment formatting did not render");}
  window.SelectPreviewTab(1);Pump();
  window.Formatting.Edit(session.HistoryPosition,d=>d.Cells[FormattingStore.CellKey("Task",task.Uid,"Name")]=originalStyle with{Italic=false});session.Rename(task.Uid,"Mixed history test");window.RefreshForValidation();window.Formatting.Edit(session.HistoryPosition,d=>d.Cells[FormattingStore.CellKey("Task",task.Uid,"Name")]=originalStyle with{Bold=false,Italic=false});window.UndoEdit();Assert(window.Formatting.Get("Task",task.Uid,"Name").Bold==true,"Mixed Undo did not restore latest style");window.UndoEdit();Assert(session.Document!.Tasks.GetByUid(task.Uid).Name==original,"Mixed Undo skipped model edit");window.UndoEdit();Assert(window.Formatting.Get("Task",task.Uid,"Name").Italic,"Mixed Undo skipped earlier style");window.RedoEdit();Assert(!window.Formatting.Get("Task",task.Uid,"Name").Italic,"Mixed Redo missed earlier style");window.RedoEdit();Assert(session.Document!.Tasks.GetByUid(task.Uid).Name=="Mixed history test","Mixed Redo skipped model edit");window.RedoEdit();Assert(window.Formatting.Get("Task",task.Uid,"Name").Bold==false,"Mixed Redo missed final style");window.UndoEdit();window.UndoEdit();window.UndoEdit();window.Formatting.Edit(session.HistoryPosition,d=>d.Cells[FormattingStore.CellKey("Task",task.Uid,"Name")]=originalStyle);Assert(!session.CanRedo&&!window.Formatting.CanRedo,"New formatting edit did not clear redo branch");Pump();
  try{new TextFormat{Size=999}.Checked();Assert(false,"Invalid font size accepted");}catch(ArgumentException){checks++;}try{new TextFormat{Foreground="bad color"}.Checked();Assert(false,"Invalid color accepted");}catch(ArgumentException){checks++;}
  var formatDialog=new TextFormatWindow(window.Formatting.Get("Task",task.Uid,"Name"));formatDialog.Show(window);Pump();using(var frame=formatDialog.CaptureRenderedFrame()!)frame.Save(Path.Combine(output,"text-format-inspector.png"));Assert(formatDialog.GetVisualDescendants().OfType<ComboBox>().Count()>=6,"Format inspector missing controls");formatDialog.Close();
  var colorDialog=new OfficeColorWindow("Font color","#804472C4");colorDialog.Show(window);Pump();using(var frame=colorDialog.CaptureRenderedFrame()!)frame.Save(Path.Combine(output,"office-color-picker.png"));Assert(colorDialog.GetVisualDescendants().OfType<NumericUpDown>().Count()==7,"RGB/alpha/HSL controls missing");var channels=colorDialog.GetVisualDescendants().OfType<NumericUpDown>().ToArray();channels[0].Value=255;Pump();Assert(colorDialog.GetVisualDescendants().OfType<TextBox>().Any(t=>t.Text?.Contains("ff72c4",StringComparison.OrdinalIgnoreCase)==true),"RGB color changes did not update hexadecimal value");colorDialog.Close();var chartDialog=new ChartColorsWindow(window.Formatting.Document.ChartColors);chartDialog.Show(window);Pump();Assert(chartDialog.GetVisualDescendants().OfType<Button>().Count(b=>Equals(b.Content,"Choose…"))==9,"Chart palette missing color targets");using(var frame=chartDialog.CaptureRenderedFrame()!)frame.Save(Path.Combine(output,"chart-color-inspector.png"));chartDialog.Close();
  var rich=new RichNote{Text="Planning notes\nReview <script>alert(1)</script> & costs."};rich.Format(0,8,f=>f with{Bold=true,Foreground="#4472C4",Highlight="#FFF2CC"});Assert(rich.FormatAt(1).Bold==true&&rich.FormatAt(12).Bold!=true,"Rich selection formatting leaked outside range");rich.ReplaceText("New "+rich.Text);Assert(rich.FormatAt(5).Bold==true,"Rich formatting shifted incorrectly after typing");Assert(rich.Html().Contains("&lt;script&gt;")&&!rich.Html().Contains("<script>"),"Rich HTML did not escape task text");Assert(rich.Html().Contains("rgba(68,114,196,1)"),"HTML colors did not preserve RGBA values");
  var paragraphs=new RichNote{Text="One\nTwo",Paragraphs=new(){[0]=new(){After=4},[4]=new(){Alignment="Right"}}};paragraphs.ReplaceText("Two");Assert(paragraphs.Paragraphs.Count==1&&paragraphs.Paragraphs[0].Alignment=="Right","Merged paragraph anchors failed on deletion");try{new RichNote{Text="A",Runs=[new(5,2,new())]}.Checked();Assert(false,"Invalid rich range accepted");}catch(ArgumentException){checks++;}
  var notes=new RichNotesWindow("Notes · Planning",rich);notes.Show(window);Pump();notes.Editor.SelectionStart=0;notes.Editor.SelectionEnd=3;notes.Format(f=>f with{Italic=true,Underline="Dotted",Vertical="Superscript"});Pump();Assert(notes.Note.FormatAt(1).Italic&&notes.Note.FormatAt(1).Vertical=="Superscript","Notes editor formatting did not apply selection");notes.Undo();Assert(notes.Note.FormatAt(1).Italic==false,"Notes Undo failed");notes.Redo();Assert(notes.Note.FormatAt(1).Italic,"Notes Redo failed");using(var frame=notes.CaptureRenderedFrame()!)frame.Save(Path.Combine(output,"rich-notes-editor.png"));notes.Close();
  window.Formatting.Edit(session.HistoryPosition,d=>{d.Notes[task.Uid]=rich;d.Bars[task.Uid]="#7030A0";d.Styles["My Style"]=new(){Bold=true,Foreground="#4472C4"};});Pump();Assert(window.Formatting.Document.Notes[task.Uid].Runs.Count>0&&window.Formatting.Document.Styles.Count==1,"Notes/named styles were not retained");
  var copy=Path.Combine(output,"format-copy-"+Guid.NewGuid()+".mpp");session.SaveCopy(copy);window.Formatting.Export(copy);Assert(File.ReadAllBytes(copy).SequenceEqual(File.ReadAllBytes(file)),"Appearance-only MPP save changed original bytes");Assert(File.Exists(copy+".projectdesk.json"),"Companion appearance file not saved");
  using var copied=new ProjectSession();copied.Open(copy);var p2=new ViewPreferences();var store=new FormattingStore(p2,()=>{});store.Bind(copied);Assert(store.Get("Task",task.Uid,"Name").Foreground=="#C00000","Companion formatting did not reload");Assert(store.Document.Notes[task.Uid].Text==rich.Text,"Rich note did not reload");Assert(store.Document.ChartColors["Task"]=="#7030A0"&&store.Document.Styles["My Style"].Bold==true,"Chart colors or named styles did not reload");
  var glass=window.GetVisualDescendants().OfType<GlassNavigationSurface>().Single();Assert(ReferenceEquals(window.Sheet.Grid.Background,DesignTokens.Surface),"Glass leaked into task content surface");glass.SetAppearance(false,false);Pump();Assert(!glass.IsReduced&&glass.GetVisualDescendants().OfType<ExperimentalAcrylicBorder>().Single().IsVisible,"Glass navigation layer did not activate");glass.SetAppearance(false,true);Pump();Assert(glass.IsReduced&&!glass.GetVisualDescendants().OfType<ExperimentalAcrylicBorder>().Single().IsVisible,"Solid fallback kept transparency active");window.UpdateGlassNavigation();var viewMenu=window.GetVisualDescendants().OfType<Menu>().Single().Items.OfType<MenuItem>().Single(m=>Equals(m.Header,"View"));var reduce=viewMenu.Items.OfType<MenuItem>().Single(m=>Equals(m.Header,"Reduce Transparency"));reduce.RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));Pump();Assert(glass.IsReduced&&ViewPreferences.Load(prefPath).ReduceTransparency,"Reduce Transparency preference did not apply/persist");using(var frame=window.CaptureRenderedFrame()!)frame.Save(Path.Combine(output,"solid-controls-grid.png"));reduce.RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));window.Formatting.Edit(session.HistoryPosition,d=>d.ChartColors.Remove("Weekend"));Application.Current!.RequestedThemeVariant=Avalonia.Styling.ThemeVariant.Dark;Pump();Assert(IsDark(DesignTokens.Surface.Color)&&IsDark(DesignTokens.TimelineFill.Color)&&!IsDark(DesignTokens.Text.Color),"Dark content / timeline surfaces did not adapt");using(var frame=window.CaptureRenderedFrame()!)frame.Save(Path.Combine(output,"dark-glass-grid.png"));Application.Current.RequestedThemeVariant=Avalonia.Styling.ThemeVariant.Light;Pump();Assert(DesignTokens.Surface.Color==Colors.White,"Light content surface did not recover");using(var frame=window.CaptureRenderedFrame()!)frame.Save(Path.Combine(output,"light-glass-grid.png"));
  var saved=ViewPreferences.Load(prefPath);Assert(saved.Appearance.Count>0,"Formatting preferences did not persist");window.CloseForValidation();Console.WriteLine($"PASS: {checks} formatting checks; task render/edit, colors, inspector, rich text/HTML, Undo/Redo, companion reload and unchanged MPP bytes.");return 0;
 }
}
